#!/usr/bin/env python3
"""Generic persistent vrnetlab launcher generated by dNLab."""
import json
import logging
import os
import re
from pathlib import Path
import vrnetlab

SPEC = json.loads(Path("/opt/generic/spec.json").read_text(encoding="utf-8"))


def resolve_resource(primary, alias, default, low, high):
    """Resolve one positive integer; only absence permits fallback."""
    if primary in os.environ:
        raw, source = os.environ[primary], primary
    elif alias in os.environ:
        raw, source = os.environ[alias], alias
    else:
        raw, source = default, "SPEC." + ("vcpu" if primary == "VCPU" else "ram_mb")
    if not re.fullmatch(r"[0-9]+", str(raw)):
        raise ValueError(f"{source} must be an integer between {low} and {high}")
    try:
        value = int(raw)
    except ValueError:
        raise ValueError(f"{source} must be an integer between {low} and {high}") from None
    if not low <= value <= high:
        raise ValueError(f"{source} must be between {low} and {high}")
    return value, source


class GenericVM(vrnetlab.VM):
    def __init__(self):
        vcpu, cpu_source = resolve_resource("VCPU", "QEMU_SMP", SPEC["vcpu"], 1, 64)
        ram_mb, ram_source = resolve_resource("RAM", "QEMU_MEMORY", SPEC["ram_mb"], 256, 1048576)
        # vrnetlab properties consult these aliases while building qemu_args;
        # discordant aliases must not override the dNLab per-node contract.
        os.environ["QEMU_SMP"] = str(vcpu)
        os.environ["QEMU_MEMORY"] = str(ram_mb)
        logging.getLogger(__name__).info(
            "generic_vm resources: vcpu=%d source=%s ram_mb=%d source=%s",
            vcpu, cpu_source, ram_mb, ram_source,
        )
        super().__init__(username="admin", password="admin", disk_image="/opt/generic/disk.qcow2",
                         ram=ram_mb, smp=str(vcpu), min_dp_nics=SPEC["data_ports"])
        self.nic_type = "virtio-net-pci" if SPEC["nic_model"] == "virtio" else "e1000"
        self.num_nics = SPEC["data_ports"]
        self.conn_mode = "tc"
        if SPEC["firmware"] == "uefi":
            self.qemu_args.extend(["-drive", "if=pflash,format=raw,readonly=on,file=/opt/generic/OVMF_CODE.fd",
                                   "-drive", "if=pflash,format=raw,file=/persist/OVMF_VARS.fd"])

    def bootstrap_spin(self):
        if self.tn is not None:
            self.tn.close()
            self.tn = None
        self.running = True

class GenericVR(vrnetlab.VR):
    def __init__(self):
        super().__init__("admin", "admin")
        self.vms = [GenericVM()]

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO, format="%(levelname)s %(message)s")
    vrnetlab.boot_delay()
    GenericVR().start()
